/* pre: question 26
   post: return an index of data such that
   data[return value] == t or -1 if t is
   not present in data.
*/
public int search(int[] data, int t) {
  int s = 0;
  int e = data.length - 1;
  int r = -1;
  while(r < 0 && s < e) {
    int m = (s + e) / 2;
    if( data[m] == t )
      r = m;
    else if(t > data[m])
      s = m + 1;
    else
      e = m - 1;
  }
  return r;
}

